def _trusted_orderbook_touch_ticks(*, price=10_000, count=10, hhmm="10:00"):
    ticks = []
    for idx in range(count):
        ticks.append(
            {
                "time": f"{hhmm}:{10 - idx:02d}",
                "price": price,
                "volume": 10 + idx,
                "best_ask": price,
                "best_bid": price - 10,
                "aggressor_source": "orderbook_touch",
                "aggressor_quality": "touch_or_crossed_ask",
                "aggressor_quote_source": "inline_0B_top_of_book",
                "strength": 120.0,
            }
        )
    return ticks


def _micro_vwap_candles(*, price=10_000, count=5):
    now = datetime.now()
    return [
        {
            "체결시간": (now - timedelta(minutes=(count - idx - 1))).strftime(
                "%H:%M:%S"
            ),
            "현재가": price,
            "고가": price + 20,
            "저가": price - 20,
            "거래량": 1_000 + idx,
        }
        for idx in range(count)
    ]


def test_caution_weak_liquidity_combo_is_observation_only_for_rising_missed(
    monkeypatch,
):
    monkeypatch.delenv(
        "KORSTOCKSCAN_CAUTION_WEAK_LIQUIDITY_ENTRY_BLOCK_ENABLED", raising=False
    )
    monkeypatch.delenv(
        "KORSTOCKSCAN_RISING_MISSED_CAUTION_WEAK_LIQUIDITY_BLOCK_ENABLED", raising=False
    )

    decision = state_handlers._evaluate_caution_weak_liquidity_entry_block(
        stock={"rising_missed_normal_buy_bridge_allowed": True},
        runtime={},
        strategy="SCALPING",
        latency_gate={
            "latency_state": "CAUTION",
            "entry_price_gap_profile": "weak_liquidity_wide_spread",
        },
        guard_fields={
            "pre_submit_liquidity_guard_action": "NOT_AVAILABLE",
            "pre_submit_liquidity_reason": "liquidity_not_available",
        },
    )

    assert decision["blocked"] is False
    assert decision["block_reason"] == "ok"
    assert decision["threshold_family"] == "caution_weak_liquidity_entry_block"
    assert decision["rising_missed_entry_lineage"] is True
    assert decision["rising_missed_liquidity_observation_only"] is True
    assert decision["decision_authority"] == "rising_missed_liquidity_attribution_only"
    assert decision["gate_action"] == "observe_only"
    assert decision["runtime_effect"] is False
    assert decision["actual_order_submitted"] is False
    assert decision["broker_order_forbidden"] is False


def test_caution_weak_liquidity_combo_blocks_general_buy_entry(monkeypatch):
    monkeypatch.delenv(
        "KORSTOCKSCAN_CAUTION_WEAK_LIQUIDITY_ENTRY_BLOCK_ENABLED", raising=False
    )
    monkeypatch.delenv(
        "KORSTOCKSCAN_RISING_MISSED_CAUTION_WEAK_LIQUIDITY_BLOCK_ENABLED", raising=False
    )

    decision = state_handlers._evaluate_caution_weak_liquidity_entry_block(
        stock={},
        runtime={},
        strategy="SCALPING",
        latency_gate={
            "latency_state": "CAUTION",
            "entry_price_gap_profile": "weak_liquidity_wide_spread",
        },
        guard_fields={
            "pre_submit_liquidity_guard_action": "NOT_AVAILABLE",
            "pre_submit_liquidity_reason": "liquidity_not_available",
        },
    )

    assert decision["blocked"] is True
    assert decision["rising_missed_entry_lineage"] is False
    assert decision["threshold_family"] == "caution_weak_liquidity_entry_block"


def test_rising_missed_missing_liquidity_is_observation_only_when_latency_safe(
    monkeypatch,
):
    monkeypatch.delenv(
        "KORSTOCKSCAN_CAUTION_WEAK_LIQUIDITY_ENTRY_BLOCK_ENABLED", raising=False
    )
    monkeypatch.delenv(
        "KORSTOCKSCAN_RISING_MISSED_CAUTION_WEAK_LIQUIDITY_BLOCK_ENABLED", raising=False
    )

    decision = state_handlers._evaluate_caution_weak_liquidity_entry_block(
        stock={"rising_missed_one_share_entry_forced": True},
        runtime={},
        strategy="SCALPING",
        latency_gate={
            "latency_state": "SAFE",
            "entry_price_gap_profile": "normal",
        },
        guard_fields={
            "pre_submit_liquidity_guard_action": "NOT_AVAILABLE",
            "pre_submit_liquidity_reason": "liquidity_not_available",
        },
    )

    assert decision["blocked"] is False
    assert decision["block_reason"] == "ok"
    assert decision["rising_missed_entry_lineage"] is True
    assert decision["rising_missed_liquidity_observation_only"] is True
    assert decision["decision_authority"] == "rising_missed_liquidity_attribution_only"
    assert decision["gate_action"] == "observe_only"
    assert decision["runtime_effect"] is False
    assert decision["actual_order_submitted"] is False
    assert decision["broker_order_forbidden"] is False


def test_pre_submit_micro_unavailable_guard_blocks_missing_context(monkeypatch):
    monkeypatch.delenv(
        "KORSTOCKSCAN_PRE_SUBMIT_MICRO_UNAVAILABLE_GUARD_ENABLED", raising=False
    )

    decision = state_handlers._pre_submit_micro_unavailable_guard_fields(
        strategy="SCALPING",
        orderbook_fields={
            "orderbook_micro_ready": False,
            "orderbook_micro_state": "insufficient",
            "orderbook_micro_reason": "missing_snapshot",
        },
        microstructure_fields={
            "micro_vwap_available": False,
            "tick_context_quality": "not_evaluated",
            "tick_accel_source": "not_evaluated",
            "tick_aggressor_pressure_usable": False,
            "tick_aggressor_trusted_count": 0,
        },
    )

    assert decision["blocked"] is True
    assert decision["threshold_family"] == "pre_submit_micro_unavailable_guard"
    assert decision["broker_order_forbidden"] is True
    assert "micro_vwap_missing" in decision["pre_submit_micro_unavailable_reason"]
    assert (
        "tick_context_not_evaluated" in decision["pre_submit_micro_unavailable_reason"]
    )


