def test_holding_flow_override_passes_micro_estimator_fields_to_ai(monkeypatch):
    now_ts = 1_783_472_100.0
    captured_ctx = {}
    logs = []

    class DummyAI:
        def evaluate_scalping_holding_flow(
            self,
            name,
            code,
            ws_data,
            recent_ticks,
            recent_candles,
            position_ctx,
            **kwargs,
        ):
            captured_ctx.update(position_ctx)
            return {
                "action": "HOLD",
                "score": 72,
                "reason": "test_hold",
                "flow_state": "UPTREND",
                "evidence": ["supportive_micro_context"],
                # Provider results may echo holding-context provenance. The
                # runtime context remains the canonical log-field owner.
                "holding_context_schema": "provider_echo_should_not_override",
            }

    real_rule_bool = state_handlers._rule_bool

    def fake_rule_bool(key, default=False):
        if key in {
            "HOLDING_FLOW_OFI_SMOOTHING_OVERRIDE_ENABLED",
            "NEVER_GREEN_DEFER_CLAMP_ENABLED",
        }:
            return False
        return real_rule_bool(key, default)

    monkeypatch.setattr(state_handlers, "_rule_bool", fake_rule_bool)
    monkeypatch.setattr(state_handlers.time, "time", lambda: now_ts)
    monkeypatch.setattr(
        state_handlers.kiwoom_utils,
        "get_tick_history_ka10003",
        lambda *args, **kwargs: [{"price": 10100, "volume": 10, "timestamp": now_ts}],
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_utils,
        "get_minute_candles_ka10080",
        lambda *args, **kwargs: [],
    )
    monkeypatch.setattr(
        state_handlers,
        "_log_holding_pipeline",
        lambda stock, code, stage, **fields: logs.append((stage, fields)),
    )

    proceed = state_handlers._evaluate_holding_flow_override(
        stock={
            "id": 32,
            "name": "HOLD_AUX",
            "strategy": "SCALPING",
            "buy_price": 10000,
            "last_reversal_features": {
                "buy_pressure_10t": 62.0,
                "net_aggressive_delta_10t": 320.0,
                "feature_extracted_at": now_ts - 1.0,
            },
        },
        code="123471",
        strategy="SCALPING",
        ws_data={
            "curr": 10100,
            "last_ws_update_ts": now_ts,
            "quote_stale": False,
            "quote_age_ms": 100.0,
            "best_bid": 10090,
            "best_ask": 10100,
            "best_bid_qty": 900,
            "best_ask_qty": 300,
            "bid_tot": 9000,
            "ask_tot": 3000,
        },
        ai_engine=DummyAI(),
        exit_rule="scalp_trailing_take_profit",
        sell_reason_type="TRAILING",
        reason="test_exit_candidate",
        profit_rate=1.0,
        peak_profit=1.2,
        drawdown=0.2,
        current_ai_score=70.0,
        held_sec=180,
        curr_price=10100,
        buy_price=10000,
        now_ts=now_ts,
    )

    assert proceed is False
    assert (
        captured_ctx["holding_flow_micro_estimator_decision_authority"]
        == "feature_only_micro_estimator_state"
    )
    assert (
        captured_ctx["holding_flow_micro_estimator_standalone_order_authority"] is False
    )
    assert captured_ctx["holding_flow_micro_estimator_runtime_effect"] is False
    assert (
        "standalone_exit" in captured_ctx["holding_flow_micro_estimator_forbidden_uses"]
    )
    review_fields = next(
        fields for stage, fields in logs if stage == "holding_flow_override_review"
    )
    assert review_fields["holding_context_schema"] == "holding_decision_context_v1"
    assert any(stage == "holding_flow_override_defer_exit" for stage, _fields in logs)


