        SCALPING_PYRAMID_STRONG_CONTINUATION_ENABLED=True,
        SCALPING_PYRAMID_STRONG_CONTINUATION_MIN_PROFIT_PCT=0.9,
        SCALPING_PYRAMID_STRONG_CONTINUATION_MAX_DRAWDOWN_PCT=0.20,
