    assert "reversal_feature_stale_reason" in logs[0][1]
    assert "spread_bps" in logs[0][1]

    now["ts"] = 1_010.0
    emitted_again = state_handlers._emit_stat_action_decision_snapshot(
        stock=stock,
        code="123456",
        strategy="SCALPING",
        ws_data=ws_data,
        chosen_action="hold_wait",
    )
    assert emitted_again is False
    assert len(logs) == 1


