def test_post_probe_first_confirmation_refreshes_and_selects_recovery_leg(
    monkeypatch,
):
    base_ts = time.time()
    active_date = (
        datetime.fromtimestamp(base_ts, tz=state_handlers._KST).date().isoformat()
    )
