def test_real_pyramid_score_50_retry_success_allows_dynamic_qty(monkeypatch):
    rules = replace(
        CONFIG,
        MAX_POSITION_PCT=1.0,
        INVEST_RATIO_SCALPING_MIN=0.10,
        INVEST_RATIO_SCALPING_MAX=0.30,
        SCALPING_SCALE_IN_DYNAMIC_QTY_ENABLED=True,
        SCALPING_PYRAMID_MIN_AI_SCORE=70,
    )
    monkeypatch.setattr(scale_in, "TRADING_RULES", rules)
    monkeypatch.setattr(state_handlers, "TRADING_RULES", rules)
    monkeypatch.setattr(state_handlers, "KIWOOM_TOKEN", "TOKEN")
    monkeypatch.setattr(
        state_handlers.kiwoom_utils,
        "get_tick_history_ka10003",
        lambda *args, **kwargs: [{"time": "09:01:00", "price": 30_600, "volume": 10}],
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_utils,
        "get_minute_candles_ka10080",
        lambda *args, **kwargs: [
            {"현재가": 30_600, "고가": 30_700, "저가": 30_500, "거래량": 1000}
        ],
    )
    monkeypatch.setattr(
        state_handlers,
        "_pre_submit_input_snapshot_needs_rest_orderbook_recheck",
        lambda *args, **kwargs: False,
    )
    context_call = {}
    ai_position_context = {}

    def capture_holding_context(**kwargs):
        context_call.update(kwargs)
        return {
            "schema": "holding_decision_context_v1",
            "enabled": True,
            "decision_kind": "holding_score_submit_authority",
        }

    monkeypatch.setattr(
        state_handlers,
        "_build_holding_ai_decision_context",
        capture_holding_context,
    )
    monkeypatch.setattr(state_handlers.time, "time", lambda: 1_002.0)

    class FakeEngine:
        def evaluate_scalping_holding_score(self, *args, **kwargs):
            ai_position_context.update(args[5])
            return {
                "action": "HOLD",
                "score": 72,
                "ai_decision_trace_id": "trace-scale-in-retry-1",
                "holding_score_source": "live",
                "holding_score_data_quality": "fresh",
                "ai_result_source": "live",
                "ai_parse_ok": True,
                "ai_fallback_score_50": False,
            }

    stock = {
        "name": "TEST",
        "strategy": "SCALPING",
        "buy_price": 30_100,
        "buy_qty": 1,
        "holding_started_at": 900.0,
        "mfe_pct": 1.2,
        "holding_ai_score_source": "holding_ai_not_called",
        "holding_score_data_quality": "stale",
        "holding_score_effective_usable": False,
        "scale_in_ai_submit_authority_decision_trace_id": "stale-prior-trace",
        "last_reversal_features": {
            "buy_pressure_10t": 100.0,
            "tick_acceleration_ratio": 4.25,
            "large_sell_print_detected": False,
            "curr_vs_micro_vwap_bp": 30.43,
            "micro_vwap_available": True,
            "minute_candle_window_fresh": True,
            "minute_candle_context_quality": "fresh_bar_window",
            "tick_context_stale": False,
            "quote_stale": False,
            "tick_aggressor_trusted_count": 10,
            "tick_aggressor_pressure_usable": True,
        },
        "actual_order_submitted": True,
    }

    retry_fields = state_handlers._retry_holding_ai_submit_authority_before_block(
        stock=stock,
        code="200710",
        ws_data={"curr": 30_650, "best_bid": 30_600, "best_ask": 30_800},
        ai_engine=FakeEngine(),
        now_ts=1_000.0,
        current_ai_score=50,
        source_event_stage="scale_in_submit_authority_retry",
        field_prefix="scale_in_ai_authority",
    )

    assert retry_fields["scale_in_ai_authority_input_retry_attempted"] is True
    assert retry_fields["scale_in_ai_authority_input_retry_success"] is True
    assert (
        retry_fields["scale_in_ai_authority_input_retry_decision_trace_id"]
        == "trace-scale-in-retry-1"
    )
    assert retry_fields["ai_decision_trace_id"] == "trace-scale-in-retry-1"
    assert retry_fields["scale_in_ai_decision_trace_id"] == "trace-scale-in-retry-1"
    assert context_call["now_ts"] == 1_002.0
    assert context_call["include_disabled_forensics"] is True
    assert ai_position_context["curr_price"] == 30_650
    assert ai_position_context["profit_rate"] > 0
    assert ai_position_context["peak_profit"] >= ai_position_context["profit_rate"]
    assert ai_position_context["drawdown_from_peak_pct"] >= 0
    assert ai_position_context["held_sec"] == 102
    assert (
        ai_position_context["position_context_profit_rate_source"]
        == "derived_net_mark_from_retry_snapshot"
    )
    assert (
        ai_position_context["position_context_held_sec_source"]
        == "shared_position_clock"
    )
    assert "decision_authority" not in retry_fields
    assert (
        retry_fields["holding_context_decision_authority"]
        == "bounded_holding_confirmation"
    )

    # Regression: this is the exact composition that crashed the live holding
    # loop when both dictionaries contained decision_authority.
    def capture_log_fields(**fields):
        return fields

    composed_log_fields = capture_log_fields(
        decision_authority="real_scale_in_submit_source_quality_guard",
        **retry_fields,
    )
    assert (
        composed_log_fields["decision_authority"]
        == "real_scale_in_submit_source_quality_guard"
    )
    assert stock["holding_score_effective"] == 72
    assert (
        stock["scale_in_ai_submit_authority_decision_trace_id"]
        == "trace-scale-in-retry-1"
    )
    details = scale_in.describe_dynamic_scale_in_qty(
        stock=stock,
        resolved_price=30_600,
        deposit=3_657_179,
        add_type="PYRAMID",
        strategy="SCALPING",
        add_reason="scalping_pyramid_ok",
        price_resolution={"allowed": True},
        action={
            "reason": "scalping_pyramid_ok",
            "current_ai_score": 72,
            "holding_score_source": "live",
            "holding_score_data_quality": "fresh",
            "holding_score_effective_usable": True,
            "profit_rate": 1.59,
            "peak_profit": 1.59,
            **retry_fields,
        },
    )

    assert details["qty"] > 0
    assert details["pyramid_ai_score_submit_authority"] is True
    assert details["scale_in_ai_authority_input_retry_success"] is True


