def test_holding_flow_override_candidate_clears_when_exit_candidate_resolves(
    monkeypatch,
):
    from src.utils.constants import TRADING_RULES as CONFIG

    state_handlers.TRADING_RULES = replace(CONFIG, SCALE_IN_REQUIRE_HISTORY_TABLE=False)
    now_ts = 1_000_000.0
    state_handlers.COOLDOWNS = {}
    state_handlers.ALERTED_STOCKS = set()
    state_handlers.HIGHEST_PRICES = {"123456": 10_050}
    state_handlers.LAST_AI_CALL_TIMES = {}
    state_handlers.LAST_LOG_TIMES = {}
    state_handlers.DB = None

    calls = {"sell": 0, "stages": []}
    monkeypatch.setattr(
        state_handlers,
        "can_consider_scale_in",
        lambda *args, **kwargs: {"allowed": False, "reason": "test_no_add"},
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_orders,
        "send_smart_sell_order",
        lambda *args, **kwargs: (
            calls.__setitem__("sell", calls["sell"] + 1)
            or {"return_code": "0", "ord_no": "S1"}
        ),
    )
    monkeypatch.setattr(
        state_handlers,
        "_log_holding_pipeline",
        lambda stock, code, stage, **fields: calls["stages"].append((stage, fields)),
    )

    stock = {
        "id": 1,
        "code": "123456",
        "name": "TEST",
        "status": "HOLDING",
        "strategy": "SCALPING",
        "buy_price": 10_000,
        "buy_qty": 1,
        "rt_ai_prob": 0.68,
        "holding_flow_override_candidate_key": "scalp_soft_stop_pct:LOSS",
        "holding_flow_override_started_at": now_ts - 240,
        "holding_flow_override_candidate_profit": -1.80,
        "holding_flow_override_last_review_at": now_ts - 210,
        "holding_flow_override_last_action": "HOLD",
    }

    state_handlers.handle_holding_state(
        stock=stock,
        code="123456",
        ws_data={"curr": 10_050},
        admin_id=1,
        market_regime="BULL",
        now_ts=now_ts,
        now_dt=datetime(2026, 5, 4, 10, 5, 0),
        radar=None,
        ai_engine=None,
    )

    assert calls["sell"] == 0
    assert "holding_flow_override_candidate_key" not in stock
    assert any(
        stage == "holding_flow_override_candidate_cleared"
        for stage, _ in calls["stages"]
    )


@pytest.mark.parametrize(
    ("executed_type", "requested_type"),
    [
        ("AVG_DOWN", "AVG_DOWN"),
        ("PYRAMID", "PYRAMID"),
    ],
)
def test_execute_scale_in_order_blocks_second_execution_of_same_type_before_broker(
    monkeypatch,
    executed_type,
    requested_type,
):
    logs = []
    broker_calls = []
    monkeypatch.setattr(
        state_handlers,
        "_log_holding_pipeline",
        lambda stock, code, stage, **fields: logs.append((stage, fields)),
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_orders,
        "send_buy_order",
        lambda *args, **kwargs: broker_calls.append((args, kwargs)),
    )
    stock = {
        "name": "TEST",
        "code": "123456",
        "strategy": "SCALPING",
        "avg_down_count": int(executed_type == "AVG_DOWN"),
        "pyramid_count": int(executed_type == "PYRAMID"),
        "last_add_type": executed_type,
    }

    result = state_handlers.execute_scale_in_order(
        stock=stock,
        code="123456",
        ws_data={"curr": 10000},
        action={"add_type": requested_type, "reason": "scale_in_test"},
        admin_id=1,
    )

    assert result is None
    assert broker_calls == []
    assert logs[0][0] == "scale_in_execution_limit_block"
    assert logs[0][1]["scale_in_type"] == requested_type
    assert logs[0][1]["scale_in_type_execution_count"] == 1
    assert logs[0][1]["scale_in_max_executions_per_type"] == 1
    assert logs[0][1]["actual_order_submitted"] is False
    assert logs[0][1]["broker_order_forbidden"] is True


