@pytest.mark.parametrize(
    ("stock", "requested_qty", "expected_allowed", "expected_remaining"),
    [
        (
            {"buy_qty": 10, "initial_buy_qty": 10, "scale_in_filled_qty": 0},
            100,
            True,
            15,
        ),
        (
            {"buy_qty": 24, "initial_buy_qty": 10, "scale_in_filled_qty": 14},
            5,
            True,
            1,
        ),
        (
            {"buy_qty": 25, "initial_buy_qty": 10, "scale_in_filled_qty": 15},
            1,
            False,
            0,
        ),
    ],
)
def test_scale_in_quantity_limit_is_aggregate_1_5x_initial_qty(
    stock, requested_qty, expected_allowed, expected_remaining
):
    decision = state_handlers._scale_in_quantity_limit_decision(
        stock,
        requested_qty=requested_qty,
    )

    assert decision["allowed"] is expected_allowed
    assert decision["remaining_scale_in_qty"] == expected_remaining
    assert decision["max_scale_in_qty"] == 15
    assert decision["allowed_qty"] == min(requested_qty, expected_remaining)


def test_scale_in_quantity_limit_initializes_new_position_baseline():
    stock = {"buy_qty": 7}

    decision = state_handlers._scale_in_quantity_limit_decision(
        stock,
        requested_qty=20,
        initialize=True,
    )

    assert stock["initial_buy_qty"] == 7
    assert stock["scale_in_filled_qty"] == 0
    assert decision["allowed_qty"] == 10


def test_timeout_pending_add_attempts_cancel_before_clear(monkeypatch):
    _mock_exact_order_terminal(monkeypatch)
    from src.utils.constants import TRADING_RULES as CONFIG

    state_handlers.TRADING_RULES = replace(CONFIG, SCALE_IN_REQUIRE_HISTORY_TABLE=False)
    state_handlers.KIWOOM_TOKEN = "token"

    cancel_calls = []

    monkeypatch.setattr(
        state_handlers.kiwoom_orders,
        "send_cancel_order",
        lambda **kwargs: cancel_calls.append(kwargs) or {"return_code": "0"},
    )

    stock = {
        "name": "TEST",
        "code": "123456",
        "status": "HOLDING",
        "strategy": "SCALPING",
        "buy_price": 10000,
        "buy_qty": 10,
        "pending_add_order": True,
        "pending_add_type": "AVG_DOWN",
        "pending_add_ord_no": "A1",
        "pending_add_requested_at": 1.0,
    }

    monkeypatch.setattr(state_handlers.time, "time", lambda: 100.0)
    result = state_handlers.can_consider_scale_in(
        stock=stock,
        code="123456",
        ws_data={"curr": 10000},
        strategy="SCALPING",
        market_regime="BULL",
    )

    assert result["allowed"] is False
    assert result["reason"] == "pending_add_timeout_released"
    assert len(cancel_calls) == 1
    assert stock.get("pending_add_order") is None
    assert stock["last_add_cancel_at"] == 100.0
    assert stock["last_add_cancel_reason"] == "timeout"

    monkeypatch.setattr(state_handlers.time, "time", lambda: 101.0)
    result = state_handlers.can_consider_scale_in(
        stock=stock,
        code="123456",
        ws_data={"curr": 10000},
        strategy="SCALPING",
        market_regime="BULL",
    )

    assert result["allowed"] is False
    assert result["reason"] == "scale_in_cancel_cooldown"


