def test_scalping_pre_ai_context_reaches_ai_and_blocks_low_liquidity_at_submit(
    monkeypatch,
):
    # Opening Rotation now owns its complete one-share lifecycle and no longer
    # hands off to the general Entry-AI path.  This test covers only the general
    # soft-context route; dedicated owner behavior lives in test_opening_rotation.
    soft_gate_enabled = True
    opening_rotation_handoff = False

    class FixedDateTime(datetime):
        @classmethod
        def now(cls, tz=None):
            return cls(2026, 5, 18, 13, 55, 0)

    state_handlers.datetime = FixedDateTime
    state_handlers.TRADING_RULES = replace(
        CONFIG,
        SCALP_PRE_AI_SOFT_GATE_ENABLED=soft_gate_enabled,
        SCALP_PRE_AI_SOURCE_QUALITY_BLOCK_ENABLED=True,
        SCALP_LIQUIDITY_PRE_SUBMIT_GUARD_ENABLED=True,
        SCALP_OVERBOUGHT_PULLBACK_GUARD_ENABLED=True,
        SCALP_SIM_PANIC_FORCE_NOOP=True,
    )
    state_handlers.COOLDOWNS = {}
    state_handlers.ALERTED_STOCKS = set()
    state_handlers.ACTIVE_TARGETS = []
    state_handlers.HIGHEST_PRICES = {}
    state_handlers.LAST_AI_CALL_TIMES = {}
    state_handlers.LAST_LOG_TIMES = {}
    state_handlers._SCALP_SAME_SYMBOL_LOSS_REENTRY_COOLDOWNS.clear()
    state_handlers._SCALP_LOSS_REENTRY_EVENT_CACHE.update({"date": None, "events": []})
    state_handlers.DB = _DummyDB()
    state_handlers.KIWOOM_TOKEN = "token"

    class DummyRadar:
        def get_smart_target_price(self, curr_price, **kwargs):
            return curr_price, 0.0

    class DummyAI:
        def __init__(self):
            self.seen_context = None

        def analyze_target(self, _name, ws_data, *_args, **_kwargs):
            self.seen_context = ws_data.get("scalp_pre_ai_gate_context")
            return {
                "action": "BUY",
                "score": 90,
                "reason": "confirmed",
                "ai_result_source": "live",
                "ai_parse_ok": True,
                **_fresh_submit_micro_fields(),
            }

    class DummyEventBus:
        def publish(self, *args, **kwargs):
            return None

    state_handlers.EVENT_BUS = DummyEventBus()
    logs = []
    sent_orders = []

    weak_momentum = {
        "enabled": True,
        "allowed": False,
        "reason": "below_buy_ratio",
        "position_tag": "SCANNER",
        "threshold_profile": "default",
        "base_vpw": 100.0,
        "current_vpw": 100.0,
        "vpw_delta": 0.0,
        "slope_per_sec": 0.0,
        "window_sec": 8,
        "elapsed_sec": 8.0,
        "window_total_value": 100_000,
        "window_buy_value": 48_000,
        "window_sell_value": 52_000,
        "window_buy_ratio": 0.48,
        "window_exec_buy_ratio": 0.45,
        "window_net_buy_qty": -2,
    }

    monkeypatch.setattr(
        state_handlers,
        "_log_entry_pipeline",
        lambda stock, code, stage, **fields: logs.append((stage, fields)),
    )
    monkeypatch.setattr(
        state_handlers,
        "_handle_watching_opening_rotation",
        lambda stock, code, ws_data, runtime, config: (
            (
                runtime.update(
                    {
                        "opening_rotation_entry_owner_handoff": True,
                        "opening_rotation_entry_owner_handoff_reason": (
                            "pullback_not_observed"
                        ),
                        "opening_rotation_entry_owner_handoff_target": (
                            "general_scalping_ai_entry"
                        ),
                    }
                )
                if opening_rotation_handoff
                else None
            )
            or False
        ),
    )
    monkeypatch.setattr(
        state_handlers,
        "_strength_momentum_stability_recheck_decision",
        lambda *args, **kwargs: {
            "pending": bool(opening_rotation_handoff),
            "reason": (
                "transient_strength_window_unstable"
                if opening_rotation_handoff
                else "not_pending"
            ),
            "recheck_after_epoch": "1001.000",
            "recheck_delay_sec": 1,
            "recheck_attempt_count": int(opening_rotation_handoff),
            "recheck_max_attempts": 1,
        },
    )
    monkeypatch.setattr(state_handlers, "is_buy_side_paused", lambda: False)
    monkeypatch.setattr(
        state_handlers,
        "_publish_buy_signal_submission_notice",
        lambda *args, **kwargs: None,
    )
    monkeypatch.setattr(
        state_handlers,
        "evaluate_scalping_strength_momentum",
        lambda ws_data: weak_momentum,
    )
    monkeypatch.setattr(
        state_handlers, "arm_big_bite_if_triggered", lambda **kwargs: (False, {})
    )
    monkeypatch.setattr(
        state_handlers, "confirm_big_bite_follow_through", lambda **kwargs: (True, {})
    )
    monkeypatch.setattr(state_handlers, "build_tick_data_from_ws", lambda ws_data: {})
    monkeypatch.setattr(
        state_handlers.kiwoom_utils,
        "get_tick_history_ka10003",
        lambda *args, **kwargs: _trusted_orderbook_touch_ticks(
            price=10_000, hhmm="13:55"
        ),
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_utils,
        "get_minute_candles_ka10080",
        lambda *args, **kwargs: _micro_vwap_candles(price=10_000),
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_orders, "get_deposit", lambda *args, **kwargs: 1_000_000
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_orders,
        "describe_buy_capacity",
        lambda *args, **kwargs: (100_000, 95_000, 5, 0.95),
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_orders,
        "send_buy_order",
        lambda *args, **kwargs: (
            sent_orders.append(args) or {"return_code": "0", "ord_no": "O1"}
        ),
    )
    monkeypatch.setattr(
        state_handlers,
        "evaluate_live_buy_entry",
        lambda **kwargs: {
            "allowed": True,
            "mode": "normal",
            "decision": "ALLOW_NORMAL",
            "reason": "ok",
            "latency_state": "SAFE",
            "orders": [
                {
                    "tag": "normal",
                    "qty": 1,
                    "price": kwargs.get("signal_price"),
                    "tif": "DAY",
                }
            ],
            "signal_price": kwargs.get("signal_price"),
            "latest_price": kwargs.get("signal_price"),
            "computed_allowed_slippage": 0,
            "ws_age_ms": 100,
            "ws_jitter_ms": 10,
            "spread_ratio": 0.001,
            "quote_stale": False,
            "latency_danger_reasons": "",
            "order_price": kwargs.get("signal_price"),
        },
    )

    ai = DummyAI()
    stock = {
        "id": 10,
        "name": "LOWLIQ",
        "strategy": "SCALPING",
        "position_tag": "SCANNER",
        "prob": 0.9,
        "rt_ai_prob": 0.9,
    }
    state_handlers.handle_watching_state(
        stock=stock,
        code="123123",
        ws_data={
            "curr": 10_000,
            "v_pw": 100.0,
            "ask_tot": 100,
            "bid_tot": 100,
            "open": 9_950,
            "fluctuation": 1.0,
            "orderbook": {
                "asks": [{"price": 10_010, "volume": 100}],
                "bids": [{"price": 10_000, "volume": 100}],
            },
        },
        admin_id=1,
        radar=DummyRadar(),
        ai_engine=ai,
    )

    by_stage = {stage: fields for stage, fields in logs}
    assert "ai_confirmed" in by_stage
    assert "scalp_sim_entry_armed" in by_stage
    assert by_stage["blocked_strength_momentum"]["gate_action"] == "risk_context_only"
    assert by_stage["blocked_vpw"]["gate_action"] == "risk_context_only"
    assert by_stage["blocked_liquidity"]["gate_action"] == "risk_context_only"
    assert "pre_submit_liquidity_guard_block" in by_stage
    assert (
        by_stage["pre_submit_liquidity_guard_block"]["broker_order_forbidden"] is True
    )
    assert (
        by_stage["pre_submit_liquidity_guard_block"]["liquidity_guard_action"]
        == "WOULD_BLOCK"
    )
    assert (
        by_stage["pre_submit_liquidity_guard_block"]["liquidity_guard_reason"]
        == "below_min_liquidity"
    )
    assert (
        by_stage["pre_submit_liquidity_guard_block"][
            "pre_submit_liquidity_guard_action"
        ]
        == "BLOCK"
    )
    assert (
        by_stage["pre_submit_liquidity_guard_block"]["forbidden_uses"]
        == "provider_route_change/bot_restart/runtime_threshold_apply_without_approval"
    )
    assert sent_orders == []
    if opening_rotation_handoff:
        assert "opening_rotation_handoff_pre_ai_baseline_deferred" in by_stage
        assert stock["opening_rotation_handoff_deferred_pre_ai_gates"]
        assert (
            "strength_momentum_stability_recheck"
            in stock["opening_rotation_handoff_deferred_pre_ai_gates"]
        )
    assert (
        ai.seen_context["liquidity"]["threshold_family"]
        == "liquidity_pre_submit_guard_p1"
    )


def test_rising_missed_scout_quality_guard_relaxes_micro_vwap_only_conflict(
    monkeypatch,
):
    monkeypatch.delenv(
        "KORSTOCKSCAN_RISING_MISSED_SCOUT_QUALITY_GUARD_ENABLED", raising=False
    )

    decision = state_handlers._evaluate_rising_missed_scout_quality_guard(
        {
            "last_watching_ai_score": 72,
            "last_watching_ai_action": "BUY",
        },
        "067290",
        {
            "curr": 2500,
            "quote_age_ms": 150.0,
            "quote_stale": False,
            "buy_pressure_10t": 0.91,
            "curr_vs_micro_vwap_bp": -11.01,
            "true_ofi_ewma": 0.08,
            "true_ofi_sample_count": 10,
            "market_data_signed_tape_state": "buy_dominated",
            "market_data_signed_tape_sample_count": 5,
        },
        {"now_ts": 1000.0, "current_ai_score": 72.0},
        {},
    )

    assert decision["rising_missed_scout_quality_guard_blocked"] is False
