def test_pending_entry_cancel_logs_receipt_provenance(monkeypatch):
    _mock_exact_order_terminal(monkeypatch)
    logs = []
    cancel_calls = []
    monkeypatch.setattr(
        state_handlers,
        "_log_entry_pipeline",
        lambda stock, code, stage, **fields: logs.append((stage, fields)),
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_orders,
        "send_cancel_order",
        lambda **kwargs: (
            cancel_calls.append(kwargs)
            or {"return_code": "0", "ord_no": "C1", "return_msg": "정상"}
        ),
    )
    stock = {
        "id": 1,
        "name": "TEST",
        "pending_entry_orders": [
            {
                "tag": "normal",
                "qty": 1,
                "filled_qty": 0,
                "price": 91900,
                "ord_no": "O1",
                "order_type": "00",
                "status": "OPEN",
                "sent_at": time.time() - 31,
                "entry_order_lifecycle": "passive_probe",
                "entry_passive_probe_applied": True,
                "best_bid_at_submit": 92000,
                "best_ask_at_submit": 92100,
                "price_below_bid_bps": 11,
                "entry_price_ai_decision_trace_id": "entry-price-trace-1",
                "entry_price_ai_snapshot_id": "entry-price-snapshot-1",
            }
        ],
    }

    assert (
        state_handlers._cancel_pending_entry_orders(stock, "440110", force=True)
        == "cancelled"
    )
    stages = {stage: fields for stage, fields in logs}
    assert stages["entry_order_cancel_requested"]["orig_ord_no"] == "O1"
    assert (
        stages["entry_order_cancel_requested"]["entry_order_lifecycle"]
        == "passive_probe"
    )
    assert stages["entry_order_cancel_requested"]["dmst_stex_tp"] == "SOR"
    assert stages["entry_order_cancel_confirmed"]["cancel_ord_no"] == "C1"
    assert stages["entry_order_cancel_confirmed"]["submitted_price"] == 91900
    assert (
        stages["entry_order_cancel_requested"]["entry_price_ai_decision_trace_id"]
        == "entry-price-trace-1"
    )
    assert (
        stages["entry_order_cancel_confirmed"]["entry_price_ai_snapshot_id"]
        == "entry-price-snapshot-1"
    )
    assert cancel_calls[-1]["dmst_stex_tp"] == "SOR"


