def test_order_execution_notice_parses_cancel_side_separately():
    manager = KiwoomWSManager.__new__(KiwoomWSManager)

    raw_values = {
        "913": "접수",
        "9001": "A123456",
        "9203": "C1",
        "905": "매수취소",
        "907": "2",
        "900": "10",
        "902": "8",
        "903": "20,020",
        "909": "E-1",
        "910": "10,010",
        "911": "2",
        "914": "10,010",
        "915": "2",
        "919": "506550",
        "908": "090102",
        "2134": "2",
        "2135": "NXT",
        "2136": "Y",
    }
    notice = manager._parse_order_execution_notice(
        raw_values,
        source_type="00",
    )

