def test_post_submit_db_persistence_does_not_downgrade_early_fill(monkeypatch):
    captured = {}

    class Query:
        def filter_by(self, **kwargs):
            captured["filter_by"] = kwargs
            return self

        def filter(self, *criteria):
            captured["criteria"] = criteria
            return self

        def update(self, values, **kwargs):
            captured["values"] = values
            captured["update_kwargs"] = kwargs
            return 1

    class Session:
        def query(self, model):
            captured["model"] = model
            return Query()

    class SessionContext:
        def __enter__(self):
            return Session()

        def __exit__(self, exc_type, exc, tb):
            return False

    class DB:
        def get_session(self):
            return SessionContext()

    monkeypatch.setattr(state_handlers, "DB", DB())
    stock = {
        "id": 23752,
        "code": "100090",
        "name": "SK오션플랜트",
        "status": "HOLDING",
        "buy_price": 19100,
        "buy_qty": 1,
        "entry_filled_qty": 1,
        "entry_execution_broker_route": "SOR",
        "entry_execution_broker_route_resolution": "broker_response",
        "entry_execution_route_recorded_at": 1786676000.25,
    }

    updated_rows = state_handlers._persist_post_submit_db_state(
        stock,
        code="100090",
        curr_price=19110,
        requested_qty=53,
    )

    assert updated_rows == 1
    assert captured["filter_by"] == {"id": 23752}
    assert captured["criteria"]
    compiled_criterion = str(
        captured["criteria"][0].compile(compile_kwargs={"literal_binds": True})
    )
    assert "SELL_ORDERED" in compiled_criterion
    assert "COMPLETED" in compiled_criterion
    assert "EXPIRED" not in compiled_criterion
    assert captured["values"] == {
        "status": "HOLDING",
        "buy_price": 19100,
        "buy_qty": 1,
        "entry_execution_broker_route": "SOR",
        "entry_execution_broker_route_resolution": "broker_response",
        "entry_execution_route_recorded_at": 1786676000.25,
    }
    assert captured["update_kwargs"] == {"synchronize_session": False}

    conflict_stock = {
        **stock,
        "entry_execution_broker_route": "UNKNOWN",
        "entry_execution_broker_route_resolution": (
            "missing_or_conflicting_submitted_leg_routes"
        ),
    }
    updated_rows = state_handlers._persist_post_submit_db_state(
        conflict_stock,
        code="100090",
        curr_price=19110,
        requested_qty=53,
    )
    assert updated_rows == 1
    assert captured["values"]["entry_execution_broker_route"] == "UNKNOWN"
    assert captured["values"]["entry_execution_broker_route_resolution"] == (
        "missing_or_conflicting_submitted_leg_routes"
    )


@pytest.mark.parametrize("terminal_status", ["SELL_ORDERED", "COMPLETED", "EXPIRED"])
def test_post_submit_db_persistence_skips_terminal_runtime_state(
    monkeypatch, terminal_status
):
    logs = []

    class Session:
        def query(self, _model):
            raise AssertionError("terminal runtime state must not write entry DB state")

    class SessionContext:
        def __enter__(self):
            return Session()

        def __exit__(self, exc_type, exc, tb):
            return False

    class DB:
        def get_session(self):
            return SessionContext()

    monkeypatch.setattr(state_handlers, "DB", DB())
    monkeypatch.setattr(state_handlers, "log_info", logs.append)
    stock = {
        "id": 23752,
        "code": "100090",
        "name": "SK오션플랜트",
        "status": terminal_status,
        "buy_price": 19100,
        "buy_qty": 1,
        "entry_filled_qty": 1,
    }

    updated_rows = state_handlers._persist_post_submit_db_state(
        stock,
        code="100090",
        curr_price=19110,
        requested_qty=53,
    )

    assert updated_rows == 0
    assert logs and "[ENTRY_DB_STATE_PRESERVED]" in logs[-1]


def test_entry_receipt_normalizes_observed_28_33_34_35_50_cumulative_sequence(
    monkeypatch,
):
    receipts.ACTIVE_TARGETS = []
    receipts.highest_prices = {}
    receipts._get_fast_state = lambda code: None
    receipts.DB = _DummyDB()
    entry_state.TERMINAL_ENTRY_ORDERS.clear()

    db_snapshots = []
    pipeline_events = []

    class DummyThread:
        def __init__(self, target=None, args=(), daemon=None, **_kwargs):
            self._target = target
            self._args = args

        def start(self):
            if self._target:
                self._target(*self._args)

    monkeypatch.setattr(receipts.threading, "Thread", DummyThread)
    monkeypatch.setattr(
        receipts,
        "_update_db_for_buy",
        lambda _target_id, _price, _now, snapshot: db_snapshots.append(snapshot),
    )
    monkeypatch.setattr(
        receipts,
        "_log_holding_pipeline",
        lambda name, code, target_id, stage, **fields: pipeline_events.append(
            (stage, fields)
        ),
    )

    stock = {
        "id": 11742,
        "code": "279570",
        "name": "케이뱅크",
        "status": "BUY_ORDERED",
        "strategy": "KOSPI_ML",
        "position_tag": "SCANNER",
        "buy_price": 0,
        "buy_qty": 0,
        "entry_requested_qty": 50,
        "requested_buy_qty": 50,
        "pending_entry_orders": [
            {
                "tag": "normal",
                "qty": 50,
                "ord_no": "0034430",
                "status": "OPEN",
                "filled_qty": 0,
            },
        ],
    }
    receipts.ACTIVE_TARGETS.append(stock)

    receipts_by_cumulative_qty = (
        (28, 22, 280_000, 10_000, 28),
        (33, 17, 330_050, 10_010, 5),
        (34, 16, 340_070, 10_020, 1),
        (35, 15, 350_100, 10_030, 1),
    )
    for (
        cumulative_qty,
        remaining_qty,
        cumulative_amount,
        unit_price,
        unit_qty,
    ) in receipts_by_cumulative_qty:
        receipts.handle_real_execution(
            {
                "code": "279570",
                "type": "BUY",
                "order_no": "0034430",
                "price": round(cumulative_amount / cumulative_qty),
                "qty": cumulative_qty,
                "order_qty": 50,
                "remaining_qty": remaining_qty,
                "cumulative_exec_amount": cumulative_amount,
                "unit_exec_price": unit_price,
                "unit_exec_qty": unit_qty,
            }
        )

    # Exact duplicate and an out-of-order receipt must not mutate runtime/DB/lifecycle.
    receipts.handle_real_execution(
        {
            "code": "279570",
            "type": "BUY",
            "order_no": "0034430",
            "price": 10_003,
            "qty": 35,
            "order_qty": 50,
            "remaining_qty": 15,
            "cumulative_exec_amount": 350_100,
            "unit_exec_price": 10_030,
            "unit_exec_qty": 1,
        }
    )
    receipts.handle_real_execution(
        {
            "code": "279570",
            "type": "BUY",
            "order_no": "0034430",
            "price": 10_002,
            "qty": 34,
            "order_qty": 50,
            "remaining_qty": 16,
            "cumulative_exec_amount": 340_070,
            "unit_exec_price": 10_020,
            "unit_exec_qty": 1,
        }
    )
    receipts.handle_real_execution(
        {
            "code": "279570",
            "type": "BUY",
            "order_no": "0034430",
            "price": 10_014,
            "qty": 50,
            "order_qty": 50,
            "remaining_qty": 0,
            "cumulative_exec_amount": 500_700,
            "unit_exec_price": 10_040,
            "unit_exec_qty": 15,
        }
    )

    assert stock["buy_qty"] == 50
    assert stock["buy_price"] == pytest.approx(10_014.0)
    assert stock["status"] == "HOLDING"
    assert stock["_entry_receipt_filled_by_order_no"]["0034430"] == 50
    assert stock["_entry_receipt_filled_amount_by_order_no"]["0034430"] == 500_700
    assert stock["_entry_receipt_requested_by_order_no"]["0034430"] == 50
    assert [snapshot["buy_qty"] for snapshot in db_snapshots] == [28, 33, 34, 35, 50]
    fill_events = [
        fields
        for stage, fields in pipeline_events
        if stage == "position_rebased_after_fill"
    ]
    assert [event["fill_qty"] for event in fill_events] == [28, 5, 1, 1, 15]
    assert [event["fill_quality"] for event in fill_events] == [
        "PARTIAL_FILL",
        "PARTIAL_FILL",
        "PARTIAL_FILL",
        "PARTIAL_FILL",
        "FULL_FILL",
    ]
    assert all(event["receipt_economics_complete"] for event in fill_events)
    assert all(event["receipt_quantity_contract_complete"] for event in fill_events)
    assert all(event["receipt_unit_fill_consistent"] for event in fill_events)


