def test_reconcile_partial_fill_below_min_ratio_sends_exit_order(monkeypatch):
    from src.utils.constants import TRADING_RULES as CONFIG

    state_handlers.TRADING_RULES = replace(
        CONFIG,
        SCALP_PARTIAL_FILL_RATIO_GUARD_ENABLED=True,
        SCALP_PARTIAL_FILL_MIN_RATIO_DEFAULT=0.20,
        SCALP_PARTIAL_FILL_MIN_RATIO_STRONG_ABS_OVERRIDE=0.10,
        SCALP_PARTIAL_FILL_MIN_RATIO_PRESET_TP=0.00,
    )
    state_handlers.KIWOOM_TOKEN = "token"
    state_handlers.DB = _DummyDB()

    def _cancel_and_clear_entry_request(stock, *_args, **_kwargs):
        stock.pop("entry_requested_qty", None)
        stock.pop("requested_buy_qty", None)
        return "cancelled"

    monkeypatch.setattr(
        state_handlers,
        "_cancel_pending_entry_orders",
        _cancel_and_clear_entry_request,
    )
    event_logs = []
    monkeypatch.setattr(
        state_handlers,
        "_log_entry_pipeline",
        lambda stock, code, stage, **fields: event_logs.append((stage, fields)),
    )
    holding_logs = []
    monkeypatch.setattr(
        state_handlers,
        "_log_holding_pipeline",
        lambda stock, code, stage, **fields: holding_logs.append((stage, fields)),
    )
    sell_calls = []
    monkeypatch.setattr(
        state_handlers.kiwoom_orders,
        "send_sell_order_market",
        lambda **kwargs: (
            sell_calls.append(kwargs) or {"return_code": "0", "ord_no": "0000001"}
        ),
    )

    now = datetime.now().timestamp()
    stock = {
        "id": 1,
        "code": "123456",
        "name": "TEST",
        "strategy": "SCALPING",
        "status": "BUY_ORDERED",
        "buy_qty": 1,
        "entry_requested_qty": 10,
        "order_price": 10000,
        "order_time": now - 120,
        "pending_entry_orders": [
            {"ord_no": "B1", "status": "OPEN", "qty": 10, "filled_qty": 1}
        ],
    }

    state_handlers._reconcile_pending_entry_orders(stock, "123456", "SCALPING")

    assert stock["status"] == "SELL_ORDERED"
    assert stock.get("pending_sell_msg", "").startswith("partial_fill_ratio_below_min")
    assert len(sell_calls) == 1
    assert sell_calls[0]["qty"] == 1
    assert stock["sell_odno"] == "0000001"
    sell_submit = [
        fields for stage, fields in holding_logs if stage == "sell_order_sent"
    ]
    assert len(sell_submit) == 1
    assert sell_submit[0]["lifecycle_submission_leg_contract"] == (
        "exact_broker_single_order_leg_v1"
    )
    stage, fields = next(
        item for item in event_logs if item[0] == "partial_fill_reconciled"
    )
    assert stage == "partial_fill_reconciled"
    assert fields["metric_role"] == "ops_reconciliation_diagnostic"
    assert fields["decision_authority"] == "diagnostic_only_no_tuning_authority"
    assert fields["window_policy"] == "same_day_reconciliation_diagnostic"
    assert fields["sample_floor"] == "not_applicable_diagnostic"
    assert fields["primary_decision_metric"] == "none_diagnostic_only"
    assert (
        fields["source_quality_gate"]
        == "partial_fill_reconciled_contract_fields_present"
    )
    assert fields["runtime_effect"] is False
    assert fields["allowed_runtime_apply"] is False


