def test_add_receipt_with_order_no_matches_pending_add_before_ordno_bind(monkeypatch):
    receipts.ACTIVE_TARGETS = []
    receipts.highest_prices = {}
    receipts._get_fast_state = lambda code: None

    history_calls = []
    pipeline_events = []

