def _install_soft_stop_expert_test_doubles(monkeypatch):
    monkeypatch.setattr(state_handlers, "COOLDOWNS", {})
    monkeypatch.setattr(state_handlers, "ALERTED_STOCKS", set())
    monkeypatch.setattr(state_handlers, "HIGHEST_PRICES", {"123456": 10000})
    monkeypatch.setattr(state_handlers, "LAST_AI_CALL_TIMES", {})
    monkeypatch.setattr(state_handlers, "LAST_LOG_TIMES", {})
    monkeypatch.setattr(state_handlers, "DB", _DummyDB())

    class FixedDateTime(datetime):
        @classmethod
        def now(cls, tz=None):
            value = cls(2026, 5, 4, 15, 0, 0)
            if tz is not None:
                return value.replace(tzinfo=tz)
            return value

    monkeypatch.setattr(state_handlers, "datetime", FixedDateTime)
    fixed_now_ts = FixedDateTime(
        2026, 5, 4, 15, 0, 0, tzinfo=state_handlers._KST
    ).timestamp()
    monkeypatch.setattr(state_handlers.time, "time", lambda: fixed_now_ts)

    pipeline_logs = []
    exit_calls = []

    def fake_log_holding_pipeline(stock, code, stage, **fields):
        pipeline_logs.append((stage, fields))

    monkeypatch.setattr(
        state_handlers, "_log_holding_pipeline", fake_log_holding_pipeline
    )
    monkeypatch.setattr(
        state_handlers.kiwoom_orders,
        "send_smart_sell_order",
        lambda *args, **kwargs: (
            exit_calls.append(args) or {"return_code": "0", "ord_no": "S1"}
        ),
    )
    monkeypatch.setattr(
        state_handlers,
        "can_consider_scale_in",
        lambda *args, **kwargs: {"allowed": False, "reason": "test_block"},
    )
    return pipeline_logs, exit_calls


