    allowed = state_handlers._evaluate_first_touch_avgdown_decision_gate(
        stock=stock,
        ws_data={"curr": 10_000, "best_bid": 9_990, "best_ask": 10_000},
        context_fields={},
        current_ai_score=50,
        peak_profit=-0.23,
        profit_rate=-3.42,
        now_ts=1_000.0,
        ai_engine=FakeEngine(),
        code="123456",
    )

    assert allowed["allowed"] is True
